public static void Main(Args _args)
{
    ACBookInventoryUpdationController controller = ACBookInventoryUpdationController::construct();

    controller.initFromBookFormIfNeeded(_args);

    if (controller.prompt())
    {
        controller.runOperation();
    }
}

public void initFromBookFormIfNeeded(Args _args)
{
    FormRun callerFormRun = _args.caller();

    if(callerFormRun && callerFormRun.name() == formStr(ACBook))
    {
        ACBookTable bookActiveRecord = callerFormRun
            .dataSource(formDataSourceStr(ACBook, ACBookTable))
            .cursor();

        ACBookInventoryUpdationDataContract contract = this.getDataContract();
        contract.parmBookId(bookActiveRecord.Id);
    }
}

protected void new(
    IdentifierName             _className     = '',
    IdentifierName             _methodName    = '',
    SysOperationExecutionMode  _executionMode = SysOperationExecutionMode::Asynchronous)
{
    super(_className, _methodName, _executionMode);
}

public static ACBookInventoryUpdationController Construct(
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    ACBookInventoryUpdationController controller = new ACBookInventoryUpdationController(
        classStr(ACBookInventoryUpdationService),
        methodStr(ACBookInventoryUpdationService, runProcess),
        _executionMode);

    controller.parmDialogCaption("@ACItFormacionLabels:UpdateBookInventory");

    return controller;
}

public boolean validateParameters()
{
    boolean ret = super();

    if(ret)
    {
        ACBookInventoryUpdationDataContract dataContract = this.getDataContract();
        ret = this.validateBook(dataContract.parmBookId())
    && this.validateNewQty(dataContract.parmNewQty());
    }

    return ret;

}

public boolean validateBook(ACId _bookId)
{
    if(!ACBookTable::exist(_bookId))
    {
        return checkFailed(strFmt("@ACItFormacionLabels:BookDoesNotExist", _bookId));
    }

    return true;
}

public boolean validateNewQty(Qty _newQty)
{
    if(_newQty < 0)
    {
        return checkFailed("@ACItFormacionLabels:FieldQtyCannotBeZero");
    }

    return true;
}
